import { MakeLogicType, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { isUserLoggedIn } from 'lib/utils/getAppContext'
import { teamLogic } from 'scenes/teamLogic'

import { DashboardBasicType } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pinnedDashboardsModelValues {
    pinnedDashboards: DashboardBasicType[]
    pinnedDashboardsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pinnedDashboardsModelActions {
    loadCurrentTeamSuccess: (
        currentTeam: null | import('~/types').TeamPublicType,
        payload?: any
    ) => {
        currentTeam: null | import('~/types').TeamPublicType
        payload?: any
    } // teamLogic
    loadPinnedDashboards: () => any
    loadPinnedDashboardsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPinnedDashboardsSuccess: (
        pinnedDashboards: DashboardBasicType[],
        payload?: any
    ) => {
        pinnedDashboards: DashboardBasicType[]
        payload?: any
    }
}

export type pinnedDashboardsModelType = MakeLogicType<pinnedDashboardsModelValues, pinnedDashboardsModelActions>

export const pinnedDashboardsModel = kea<pinnedDashboardsModelType>([
    path(['models', 'pinnedDashboardsModel']),
    connect(() => ({
        actions: [teamLogic, ['loadCurrentTeamSuccess']],
    })),
    loaders(() => ({
        pinnedDashboards: [
            [] as DashboardBasicType[],
            {
                loadPinnedDashboards: async () => {
                    if (!isUserLoggedIn() || !teamLogic.values.currentTeam) {
                        return []
                    }

                    const response = await api.get<{ results: DashboardBasicType[] }>(
                        `api/environments/${teamLogic.values.currentTeamId}/dashboards/?pinned=true&limit=4&exclude_generated=true`
                    )
                    return response.results
                },
            },
        ],
    })),
    reducers({
        pinnedDashboards: [
            [] as DashboardBasicType[],
            {
                loadCurrentTeamSuccess: () => [],
            },
        ],
    }),
    listeners(({ actions }) => ({
        loadCurrentTeamSuccess: ({ currentTeam }) => {
            if (currentTeam) {
                actions.loadPinnedDashboards()
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadPinnedDashboards()
    }),
])
